window.Pages=(()=>{
 const {e,icon,button,badge,field,input,select,link,empty}=UI;
 const title=(name,actions='')=>UI.header(name,actions);
 const familyTag=p=>`<span class="family-tag ${p.family==='Ambit'?'violet':'teal'}">${e(p.family)}</span>`;
 function preview(p){const parts=p.views[0]?.components||[],height=Math.max(4,...parts.map(c=>(c.y||0)+(c.h||2)));return `<svg class="layout-preview" viewBox="0 0 120 ${height*8}" aria-hidden="true">${parts.map(c=>`<rect x="${(c.x||0)*10+1}" y="${(c.y||0)*8+1}" width="${Math.max(2,(c.w||6)*10-3)}" height="${Math.max(2,(c.h||2)*8-3)}" rx="2" class="preview-${c.kind}"></rect>`).join('')}</svg>`;}
 function presetFacts(p){let count=0;const channels=new Set();for(const v of p.views)Layout.walk(v.components,c=>{if(c.kind!=='group')count++;for(const id of c.channels||[])if(['chart','numeric'].includes(c.kind)){const ch=Cousins.channelInfo(c.device,id);if(ch)channels.add(ch.name);}});return {count,channels:[...channels]};}
 function presetRow(p){const facts=presetFacts(p);return `<div class="preset-detail-row" data-filter-kind="preset" data-search="${e((p.name+' '+p.family+' '+facts.channels.join(' ')).toLowerCase())}"><a class="preset-identity" href="#editor/${p.id}">${preview(p)}<span class="od-field"><strong>${e(p.name)}</strong><span class="row-subline">${e(p.profile||p.family)}<span class="revision">r${p.revision}</span></span></span></a><div class="od-field row-bindings"><span>${e(p.devices.map(id=>Cousins.getDevice(id)?.name||id).join(' + '))}</span><span class="row-subline">${p.views.length} views · ${facts.count} components</span></div><div class="channel-chips">${facts.channels.slice(0,3).map(name=>`<span>${e(name)}</span>`).join('')}</div><div class="actions">${button('Duplicate preset','duplicate-preset',{id:p.id,icon:'copy',iconOnly:true})}${link('Start','start/'+p.id,'btn','play')}</div></div>`;}
 function home(){const active=Cousins.db.collections.filter(c=>c.acquisition!=='Completed'),recent=Cousins.db.collections.filter(c=>c.acquisition==='Completed');return `<div class="page home-page">${title('Home',link('New preset','editor/new','btn primary','plus'))}<div class="operations-stats"><div class="operation-stat od-stat stat-storage"><span class="stat-label">${icon('folder')}Available browser storage</span><strong id="storage-available">Checking</strong></div><a class="operation-stat od-stat stat-devices" href="#devices"><span class="stat-label">${icon('device')}Devices connected</span><strong>${Cousins.db.devices.filter(d=>d.status==='Ready').length}</strong></a><a class="operation-stat od-stat stat-captures" href="#collections"><span class="stat-label">${icon('chart')}Active collections</span><strong>${active.length}</strong></a></div><section class="home-section"><div class="section-heading"><h2>Ongoing</h2></div>${active.length?active.map(c=>`<a class="acquisition-row" href="#active/${c.id}">${preview(c.preset)}<div class="od-field"><strong>${e(c.name)}</strong><span class="row-subline">${e(c.preset.name)} · r${c.preset.revision}</span><span class="row-subline">${e(c.preset.devices.map(id=>Cousins.getDevice(id)?.name||id).join(' + '))}</span></div><div class="od-field">${badge(c.acquisition)}<span class="row-subline">${e(c.recording||'Not recording')}</span></div><div class="od-stat"><strong class="duration">${Cousins.duration(c.seconds)}</strong><span class="row-subline">Elapsed</span></div><span class="row-open">Open ${icon('right')}</span></a>`).join(''):empty('No active acquisitions',link('Choose a preset','presets','btn'))}</section><section class="home-section"><div class="section-heading"><h2>Saved presets</h2>${link('All presets','presets','section-link','right')}</div><div class="preset-table">${Cousins.db.presets.slice(0,4).map(presetRow).join('')}</div></section><section class="home-section"><div class="section-heading"><h2>Recent collections</h2>${link('All collections','collections','section-link','right')}</div>${collectionTable(recent)}</section></div>`;}
 async function mountHome(){const element=document.getElementById('storage-available');if(!element)return;try{const result=await navigator.storage.estimate();if(!Number.isFinite(result.quota)||!Number.isFinite(result.usage))throw Error();const bytes=Math.max(0,result.quota-result.usage);element.textContent=bytes>=1073741824?(bytes/1073741824).toFixed(1)+' GB':(bytes/1048576).toFixed(0)+' MB';}catch{element.textContent='Unavailable';}}

 function presetList(){return `<div class="preset-page"><div class="page-heading">${title('Acquisition presets')}</div><div class="page-split">${App.presetSidebar()}<div class="preset-content preset-welcome"><div class="preset-start"><h2>Create a preset</h2>${Cousins.db.presets.length?'<p>Select a saved preset on the left, or start a new layout.</p>':'<p>Build a layout with charts, inputs and device controls.</p>'}${link('New preset','editor/new','btn primary','plus')}</div></div></div></div>`;}

 function start(p){if(!p)return empty('Preset not found');const missing=[];if(!p.views.some(v=>v.components.length))missing.push('empty views');for(const v of p.views)Layout.walk(v.components,c=>{if(c.device&&!Cousins.getDevice(c.device))missing.push(c.title);if(['chart','numeric'].includes(c.kind)&&(!c.channels.length||c.channels.some(id=>!Cousins.channelInfo(c.device,id))))missing.push(c.title);});return `<div class="page start-page">${title('Start collection','',link('Presets','presets')+' / '+e(p.name))}<form id="start-form" data-preset="${p.id}" class="page-form">${field('Collection name',input('name',p.name+' · '+new Date().toLocaleDateString(),'text','required maxlength="100"'))}<div class="form-section"><h2>Preset</h2><div class="summary-line"><strong>${e(p.name)}</strong><span>Revision ${p.revision}</span><span>${p.views.length} views</span>${link('Edit','editor/'+p.id,'btn quiet','sliders')}</div></div><div class="form-section"><h2>Devices</h2>${p.devices.map(id=>`<div class="setup-device">${icon('device')}<strong>${e(Cousins.getDevice(id)?.name||id)}</strong>${badge('Mock connection')}</div>`).join('')}</div>${field('If a device fails',select('policy',p.policy,[{value:'continue',label:'Continue remaining devices'},{value:'stop',label:'Stop all devices'}]))}${missing.length?`<div class="alert-strip">${icon('alert')}<span>Fix missing bindings in ${e([...new Set(missing)].join(', '))} before starting.</span></div>`:''}<div class="form-actions"><button type="submit" class="btn primary" ${missing.length?'disabled':''}>${icon('play')}Start collection</button>${link('Cancel','editor/'+p.id,'btn quiet')}</div></form></div>`;}
 function collectionTable(list){return list.length?`<div class="table-wrap"><table class="collection-table"><thead><tr><th>Collection</th><th>Preset</th><th>Duration</th><th>Recording</th><th></th></tr></thead><tbody>${list.map(c=>`<tr class="filter-row" data-filter-kind="collection" data-search="${e(c.name.toLowerCase())}"><td><a class="table-name" href="#collection/${c.id}">${e(c.name)}</a></td><td>${e(c.preset.name)}</td><td>${Cousins.duration(c.seconds)}</td><td>${Runtime.status(c.recording)}</td><td>${link(c.acquisition==='Completed'?'Replay':'Open acquisition','active/'+c.id,'btn quiet',c.acquisition==='Completed'?'play':'right')}</td></tr>`).join('')}</tbody></table></div>`:empty('No collections yet',link('Choose a preset','presets','btn'));}
 function collections(){return `<div class="page">${title('Collections')}<div class="list-toolbar"><div class="search-field">${icon('search')}<input type="search" data-filter="collection" aria-label="Search collections" placeholder="Search collections"></div><span>${Cousins.db.collections.length} collections</span></div>${collectionTable(Cousins.db.collections)}</div>`;}
 function collection(c,exporting=false){if(!c)return empty('Collection not found');return `<div class="page collection-detail">${title(c.name,`${button('Capture logs','collection-logs',{id:c.id,icon:'file',quiet:true})}${button('Rename','rename-collection',{id:c.id,quiet:true})}${button('Delete','delete-collection',{id:c.id,icon:'trash',iconOnly:true,danger:true})}${link(c.acquisition==='Completed'?'Open recording':'Open acquisition','active/'+c.id,'btn primary',c.acquisition==='Completed'?'play':'chart')}`,link('Collections','collections'))}<div class="collection-facts"><div><span>Preset</span><strong>${e(c.preset.name)} <span class="quiet-label">r${c.preset.revision}</span></strong></div><div><span>Duration</span><strong>${Cousins.duration(c.seconds)}</strong></div><div><span>Recorded</span><strong>${e(c.created)}</strong></div><div><span>Status</span>${Runtime.status(c.recording)}</div></div><div class="section-heading"><h2>Recording files</h2>${link('Extract CSV','collection/'+c.id+'/export','btn','download')}</div><div class="table-wrap"><table><thead><tr><th>File</th><th>Source</th><th>Rows</th><th>Units</th><th>Time (s)</th><th><span class="sr-only">Download</span></th></tr></thead><tbody>${c.files.map(f=>`<tr><td><button class="text-button file-name" data-action="preview-file" data-id="${f.id}">${icon('file')}${e(f.name)}</button></td><td>${e(Cousins.getDevice(f.source)?.name||f.source)}</td><td>${f.rows.toLocaleString()}</td><td>${e(f.unit)}</td><td class="numeric-cell">${f.start}–${f.end}</td><td>${button('Download Parquet','download-parquet',{id:f.id,icon:'download',quiet:true})}</td></tr>`).join('')}</tbody></table></div>${App.ui.previewFile?filePreview(c,App.ui.previewFile):''}<section class="derived-section"><div class="section-heading"><h2>Derived results</h2>${c.derived?button('Delete derived results','delete-derived',{id:c.id,icon:'trash',danger:true}):''}</div><p class="quiet-label">${c.derived?'No calculated profile results. Raw recordings are retained independently.':'Derived results removed. Raw recordings remain available.'}</p></section></div>`;}
 function filePreview(c,id){const f=c.files.find(x=>x.id===id);if(!f)return '';const channels=RecordingData.channels(c,f),rows=RecordingData.samples(c,f).slice(0,5);return `<section class="file-preview"><div class="section-heading"><h2>${e(f.name)}</h2><div class="actions">${button('Download Parquet','download-parquet',{id:f.id,icon:'download'})}${button('Close preview','preview-file',{id:'',icon:'close',iconOnly:true})}</div></div><p class="quiet-label">First ${rows.length} sample rows · ${e(f.schema)}</p><div class="table-wrap"><table><thead><tr><th>Time (s)</th>${channels.map(ch=>`<th>${e(ch.name)} (${e(ch.unit)})</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td class="numeric-cell">${r.time_s}</td>${channels.map(ch=>`<td class="numeric-cell">${r[ch.id].toFixed(3)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
 function exportForm(c){const channels=RecordingData.exportChannels(c);return `<form id="export-form" data-collection="${e(c.id)}" novalidate><header class="export-heading"><div><h2 id="export-title">Extract CSV</h2><p>${e(c.name)}</p></div>${button('Close export','close-csv',{icon:'close',iconOnly:true,quiet:true})}</header><div class="export-body"><fieldset><legend>Files</legend>${c.files.map((f,i)=>`<label class="export-file"><input type="checkbox" name="files" value="${e(f.id)}" ${i<2?'checked':''}><span class="od-field od-fill"><strong>${e(f.name)}</strong><span>${e(f.schema)} · ${e(f.unit)}</span></span><span>${f.rows.toLocaleString()} rows</span></label>`).join('')}</fieldset><fieldset><legend>Time range</legend><div class="two-fields">${field('From (s)',input('from',Math.min(...c.files.map(f=>f.start),0),'number','min="0" step="any" required'))}${field('To (s)',input('to',Math.max(...c.files.map(f=>f.end),0),'number','min="0" step="any" required'))}</div></fieldset><fieldset><legend>Channels</legend><div class="channel-options">${channels.map(ch=>`<label class="channel-option"><input type="checkbox" name="channels" value="${e(ch.id)}" checked><span class="channel-label"><strong>${e(ch.name)}</strong><span>${e(ch.unit)}</span></span></label>`).join('')}</div></fieldset><label class="check-row"><input type="checkbox" name="identity" checked><span>Include collection and source columns</span></label><p class="export-note">Exports contain the sample data shown in the file preview.</p><p class="form-error" id="export-error" role="alert" tabindex="-1"></p><p id="export-status" role="status"></p></div><footer class="export-footer">${button('Cancel','close-csv')}<button class="btn primary" type="submit">${icon('download')}Download CSV</button></footer></form>`;}
 function devices(){return `<div class="page devices-page">${title('Devices',link('Register device','register','btn primary','plus'))}<div class="list-toolbar"><div class="search-field">${icon('search')}<input type="search" data-filter="device" aria-label="Search devices" placeholder="Find a device or channel"></div><span class="scope-label">Mock connections</span></div><div class="table-wrap"><table class="device-table"><thead><tr><th>Instrument</th><th>Channels & units</th><th>Connection</th><th>Controls</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${Cousins.db.devices.map(d=>`<tr data-filter-kind="device" data-search="${e((d.name+' '+d.channels.map(c=>c.name).join(' ')).toLowerCase())}"><td><div class="od-field"><a class="table-name" href="#device/${d.id}">${e(d.name)}</a><span class="row-subline">${e(d.kind)}</span><span class="configuration-name">${e(d.definition)}</span></div></td><td><div class="device-channels">${d.channels.length?d.channels.map(c=>`<span class="device-channel"><strong>${e(c.name)}</strong><span>${e(c.unit)}</span><small>${c.shape.startsWith('Vector')?'Vector':'Scalar'}</small></span>`).join(''):'<span class="row-subline">Actuator only</span>'}</div></td><td><div class="od-field">${badge(d.status)}<span class="row-subline">${e(d.protocol||'Mock adapter')}</span></div></td><td><div class="od-field"><span>${e(d.commands.join(' / '))}</span><span class="row-subline">${e(d.parameter)} · ${d.applied} ${e(d.unit)}</span></div></td><td><div class="actions">${link('Inspect','device/'+d.id,'btn quiet')}${link('Test','test/'+d.id,'btn','play')}</div></td></tr>`).join('')||'<tr><td colspan="5">No registered devices. Register a device to get started.</td></tr>'}</tbody></table></div></div>`;}

 function device(d){if(!d)return empty('Device not found');return `<div class="page">${title(d.name,link('Test device','test/'+d.id,'btn primary','play'),link('Devices','devices'))}<div class="collection-facts"><div><span>Capabilities</span><strong>${e(d.kind)}</strong></div><div><span>Connection</span>${badge('Mock connection')}</div><div><span>Commands</span><strong>${e(d.commands.join(', '))}</strong></div></div><h2>Channels</h2><table><thead><tr><th>Channel</th><th>Data shape</th><th>Unit</th></tr></thead><tbody>${d.channels.map(c=>`<tr><td>${e(c.name)}</td><td>${e(c.shape)}</td><td>${e(c.unit)}</td></tr>`).join('')||'<tr><td colspan="3">This device provides controls only.</td></tr>'}</tbody></table><section class="form-section"><h2>Parameters</h2><div class="summary-line"><strong>${e(d.parameter)}</strong><span>${d.applied} ${e(d.unit)}</span><span class="quiet-label">Range ${d.min}–${d.max} ${e(d.unit)}</span></div></section></div>`;}
 const configExample='device:\n  name: Temperature probe\n  protocol: mock\nchannels:\n  - id: temperature\n    unit: °C\n    shape: scalar\ncommands:\n  - Start\n  - Stop\n';
 const highlight=text=>text.split('\n').map((line,i)=>{const match=line.match(/^([ \t-]*)([\w]+)(\s*[:=])(.*)$/);const colored=match?e(match[1])+'<span class="code-key">'+e(match[2])+'</span>'+e(match[3])+'<span class="code-value">'+e(match[4])+'</span>':e(line);return `<span class="code-line"><span class="line-number">${i+1}</span>${colored||' '}</span>`;}).join('');
 function register(){return `<div class="page">${title('Register device','',link('Devices','devices'))}<form id="register-form" class="page-form wide">${field('Device name',input('name','','text','required placeholder="Temperature probe"'))}<div class="two-fields">${field('Connection type',select('protocol','mock',[{value:'mock',label:'Mock device'},{value:'driver',label:'Custom driver / sidecar'},{value:'config',label:'Configuration file'}]))}${field('Capabilities',select('kind','Acquisition',['Acquisition','Control','Acquisition + control']))}</div><div class="form-section"><div class="section-heading"><h2>Device configuration</h2>${select('format','yaml',['yaml','toml'],'aria-label="Configuration format"')}</div><div class="code-editor"><pre aria-hidden="true" id="code-highlight">${highlight(configExample)}</pre><textarea name="config" id="config-code" aria-label="Device configuration" spellcheck="false" required>${e(configExample)}</textarea></div></div>${field('Driver or sidecar path',input('driver','','text','placeholder="Optional path to a local driver"'))}<div class="form-error" id="register-error" role="alert"></div><div class="form-actions"><button type="submit" class="btn primary">Register device</button>${link('Cancel','devices','btn quiet')}</div></form></div>`;}
 function test(d){if(!d)return empty('Device not found');const mode=App.ui.testMode||'mock',running=App.ui.testing;const chart=Layout.create('chart',d.id);chart.title='Channel preview';chart.h=4;return `<div class="page">${title('Test '+d.name,'',link('Devices','devices')+' / '+link(d.name,'device/'+d.id))}<div class="test-controls">${field('Input',select('test-mode',mode,[{value:'mock',label:'Mock data'},{value:'replay',label:'Recorded example'},{value:'real',label:'Real device'}],'data-test-mode'))}${field(d.parameter,`<div class="unit-input">${input('test-parameter',d.applied,'number',`min="${d.min}" max="${d.max}" step="${d.step}" id="test-parameter"`)}<span>${e(d.unit)}</span></div>`)}${button(running?'Stop test':'Run test','test-run',{id:d.id,primary:true,icon:running?'stop':'play',disabled:mode==='real'})}</div>${mode==='real'?`<div class="alert-strip">${icon('disconnect')}<span>No hardware adapter is connected.</span></div>`:`<div class="test-state">${badge(running?'Streaming':mode==='mock'?'Mock input':'Recorded input')}<span class="quiet-label">${mode==='mock'?'Interface test. No hardware connection.':'Replay from bundled sample data.'}</span></div>`}${d.channels.length?`<section class="test-chart"><h2>${e(d.channels[0].name)}</h2><div class="chart" data-chart="${e(JSON.stringify(chart))}"></div></section>`:''}<h2>Diagnostics</h2><div class="event-row"><span>${running?'00:01':'00:00'}</span><span>${running?'Input stream opened. Channel schema matches.':'Ready to test.'}</span></div><div class="table-wrap"><table><thead><tr><th>Channel</th><th>Shape</th><th>Value</th></tr></thead><tbody>${d.channels.map((c,i)=>`<tr><td>${e(c.name)}</td><td>${e(c.shape)}</td><td>${running?Cousins.signal(84,i).toFixed(2):'—'} ${e(c.unit)}</td></tr>`).join('')}</tbody></table></div></div>`;}
 function settings(){const current=Cousins.db.version,versions=[...new Set(['0.8.3','0.8.2','0.8.1',current])].sort().reverse();return `<div class="page settings-page">${title('Settings')}<section class="settings-section"><h2>Appearance</h2><div class="appearance-options">${['light','dark','system'].map(mode=>`<button class="appearance-option ${Cousins.db.appearance===mode?'selected':''}" data-action="appearance" data-id="${mode}" aria-pressed="${Cousins.db.appearance===mode}"><span class="appearance-preview ${mode}"><span></span><span></span></span><strong>${mode[0].toUpperCase()+mode.slice(1)}</strong>${Cousins.db.appearance===mode?icon('check'):''}</button>`).join('')}</div></section><section class="settings-section"><div class="section-heading"><h2>Application version</h2>${badge('Current '+current)}</div><div class="version-choice">${field('Target version',select('target-version',current,versions.map(value=>({value,label:value+(value===current?' · Current':value>current?' · Compatible upgrade':' · Compatible downgrade')})),'id="target-version"'))}${button('Current version','version',{disabled:true})}</div><div class="version-row"><div class="od-field"><strong>Offline package</strong><span>Choose a downloaded package</span></div><label class="btn">Select package<input type="file" id="offline-package" hidden accept=".zip,.tar,.gz,.AppImage,.exe,.msi"></label></div><p class="field-hint">Version changes are demonstrated here. No software is installed.</p></section><section class="settings-section"><h2>Diagnostics</h2><p>View application activity and capture errors from this browser session.</p>${button('View application logs','application-logs',{icon:'file'})}</section><section class="settings-section"><h2>About this prototype</h2><p>Acquisitions and device responses use example data. Scientific profile formulas remain unspecified. JupyterLite uses browser storage and a browser Python runtime.</p><div class="actions"><a class="btn" href="reference-board.html" target="_blank">Mobbin reference board ${icon('external')}</a><a class="btn" href="design-notes.md" target="_blank">Design notes ${icon('external')}</a></div></section></div>`;}
 function versionSelection(value){const b=document.querySelector('[data-action="version"]');if(!b)return;b.disabled=value===Cousins.db.version;b.textContent=b.disabled?'Current version':value>Cousins.db.version?'Upgrade to '+value:'Downgrade to '+value;}
 return {exportForm,mountHome,versionSelection,home,presetList,start,collections,collection,devices,device,register,test,settings,highlight,title};
})();
